create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, role text not null default 'customer' check (role in ('customer','owner','admin','support','finance')), created_at timestamptz not null default now());
create table if not exists public.products (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, game text not null, mode text not null, price numeric(12,2) not null check (price >= 0), active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete set null, product_id uuid references public.products(id) on delete restrict, player_id text not null, payment_method text not null, status text not null default 'pending' check (status in ('pending','paid','processing','completed','failed','cancelled','refunded')), amount numeric(12,2) not null check (amount >= 0), created_at timestamptz not null default now());
create index if not exists orders_user_id_idx on public.orders(user_id); create index if not exists orders_status_idx on public.orders(status); create index if not exists products_game_idx on public.products(game);
alter table public.profiles enable row level security; alter table public.products enable row level security; alter table public.orders enable row level security;
create policy "profiles own read" on public.profiles for select using (auth.uid() = id);
create policy "products public read" on public.products for select using (active = true or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in ('owner','admin','support','finance')));
create policy "orders own read" on public.orders for select using (auth.uid() = user_id or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in ('owner','admin','support','finance')));
